def longest_obstacle_course_at_each_position(obstacles):
    from bisect import bisect_right
    tails = []
    answer = []
    for height in obstacles:
        length = bisect_right(tails, height)
        if length == len(tails):
            tails.append(height)
        else:
            tails[length] = height
        answer.append(length + 1)
    return answer

